#include <stdio.h>
#include <string.h>
#include <stdbool.h>

static bool is_leap(int year) {
    if (year % 400 == 0) return true;
    if (year % 100 == 0) return false;
    return (year % 4 == 0);
}

static const int days_in_month[13] = {
    0, 31, 28, 31, 30, 31, 30,
    31, 31, 30, 31, 30, 31
};

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }
    const char *s = argv[1];
    size_t len = strlen(s);
    if (len != 10) {
        puts("INVALID");
        return 0;
    }
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) {
            if (s[i] != '-') { puts("INVALID"); return 0; }
        } else {
            if (s[i] < '0' || s[i] > '9') { puts("INVALID"); return 0; }
        }
    }
    int year = (s[0]-'0')*1000 + (s[1]-'0')*100 + (s[2]-'0')*10 + (s[3]-'0');
    int month = (s[5]-'0')*10 + (s[6]-'0');
    int day = (s[8]-'0')*10 + (s[9]-'0');
    if (month < 1 || month > 12) { puts("INVALID"); return 0; }
    int max_day = days_in_month[month];
    if (month == 2 && is_leap(year)) max_day = 29;
    if (day < 1 || day > max_day) { puts("INVALID"); return 0; }
    puts("VALID");
    return 0;
}
